items_a = [('A', 'd'), ('B', 'e')]
items_b = [('B', 'd'), ('A', 'e')]
print(len(items_a))
merged = {}
for lhs, la in items_a + items_b:
    merged.setdefault(lhs, set()).add(la)
entries = sum(len(v) for v in merged.values())
print(entries)
look = set()
for v in merged.values():
    look |= v
conf = 0
for la in look:
    if sum(1 for v in merged.values() if la in v) > 1:
        conf += 1
print(conf)
